    async fn payment_profile_remove<'payment_profile_remove_request>(&self, payment_profile_remove_request: models::PaymentProfileRemoveRequest) -> Result<models::PaymentProfileRemoveResponse, Error<PaymentProfileRemoveError>>;

    /// POST /processor/account/get
    ///
    /// This endpoint returns the account associated with a given processor token.  This endpoint retrieves cached information, rather than extracting fresh information from the institution. As a result, the account balance returned may not be up-to-date; for realtime balance information, use `/processor/balance/get` instead. Note that some information is nullable. 
    async fn processor_account_get<'processor_account_get_request>(&self, processor_account_get_request: models::ProcessorAccountGetRequest) -> Result<models::ProcessorAccountGetResponse, Error<ProcessorAccountGetError>>;

