    async fn processor_bank_transfer_create<'processor_bank_transfer_create_request>(&self, processor_bank_transfer_create_request: models::ProcessorBankTransferCreateRequest) -> Result<models::ProcessorBankTransferCreateResponse, Error<ProcessorBankTransferCreateError>>;

    /// POST /processor/identity/get
    ///
    /// The `/processor/identity/get` endpoint allows you to retrieve various account holder information on file with the financial institution, including names, emails, phone numbers, and addresses.
    async fn processor_identity_get<'processor_identity_get_request>(&self, processor_identity_get_request: models::ProcessorIdentityGetRequest) -> Result<models::ProcessorIdentityGetResponse, Error<ProcessorIdentityGetError>>;

