    async fn protect_event_send<'protect_event_send_request>(&self, protect_event_send_request: models::ProtectEventSendRequest) -> Result<models::ProtectEventSendResponse, Error<ProtectEventSendError>>;

    /// POST /protect/report/create
    ///
    /// Use this endpoint to create a Protect report to document fraud incidents, investigation outcomes, or other risk events. This endpoint allows you to report various types of incidents including account takeovers, identity fraud, unauthorized transactions, and other security events. The reported data helps improve fraud detection models and provides valuable feedback to enhance the overall security of the Plaid network. Reports can be created for confirmed incidents that have been fully investigated, or for suspected incidents that require further review. You can associate reports with specific users, sessions, or transactions to provide comprehensive context about the incident.
    async fn protect_report_create<'protect_report_create_request>(&self, protect_report_create_request: models::ProtectReportCreateRequest) -> Result<models::ProtectReportCreateResponse, Error<ProtectReportCreateError>>;

    /// POST /protect/user/insights/get
    ///
    /// Use this endpoint to get basic information about a user as it relates to their fraud profile with Protect.
    async fn protect_user_insights_get<'protect_user_insights_get_request>(&self, protect_user_insights_get_request: models::ProtectUserInsightsGetRequest) -> Result<models::ProtectUserInsightsGetResponse, Error<ProtectUserInsightsGetError>>;

    /// POST /sandbox/bank_income/fire_webhook
    ///
    /// Use the `/sandbox/bank_income/fire_webhook` endpoint to manually trigger a Bank Income webhook in the Sandbox environment.
    async fn sandbox_bank_income_fire_webhook<'sandbox_bank_income_fire_webhook_request>(&self, sandbox_bank_income_fire_webhook_request: models::SandboxBankIncomeFireWebhookRequest) -> Result<models::SandboxBankIncomeFireWebhookResponse, Error<SandboxBankIncomeFireWebhookError>>;

    /// POST /sandbox/bank_transfer/fire_webhook
    ///
    /// Use the `/sandbox/bank_transfer/fire_webhook` endpoint to manually trigger a Bank Transfers webhook in the Sandbox environment.
    async fn sandbox_bank_transfer_fire_webhook<'sandbox_bank_transfer_fire_webhook_request>(&self, sandbox_bank_transfer_fire_webhook_request: models::SandboxBankTransferFireWebhookRequest) -> Result<models::SandboxBankTransferFireWebhookResponse, Error<SandboxBankTransferFireWebhookError>>;

    /// POST /sandbox/bank_transfer/simulate
    ///
    /// Use the `/sandbox/bank_transfer/simulate` endpoint to simulate a bank transfer event in the Sandbox environment.  Note that while an event will be simulated and will appear when using endpoints such as `/bank_transfer/event/sync` or `/bank_transfer/event/list`, no transactions will actually take place and funds will not move between accounts, even within the Sandbox.
    async fn sandbox_bank_transfer_simulate<'sandbox_bank_transfer_simulate_request>(&self, sandbox_bank_transfer_simulate_request: models::SandboxBankTransferSimulateRequest) -> Result<models::SandboxBankTransferSimulateResponse, Error<SandboxBankTransferSimulateError>>;

    /// POST /sandbox/cra/cashflow_updates/update
    ///
    /// Use the `/sandbox/cra/cashflow_updates/update` endpoint to manually trigger an update for Cash Flow Updates (Monitoring) in the Sandbox environment.
