    async fn sandbox_item_set_verification_status<'sandbox_item_set_verification_status_request>(&self, sandbox_item_set_verification_status_request: models::SandboxItemSetVerificationStatusRequest) -> Result<models::SandboxItemSetVerificationStatusResponse, Error<SandboxItemSetVerificationStatusError>>;

